add({type:'canvas',section:'06 / GATEWAY · BẢO MẬT',title:'Mỗi request đi qua chuỗi filter trước khi tới service',owner:'Hoàng Anh',service:'Gateway · security filter chain',time:'2 phút',full:true,
 diagram:'flowchart LR\nR["Request<br/>/api/*"] --> F1["1 · Truy vết<br/>Correlation-Id"]\nF1 --> F2["2 · Rate limit<br/>5 lần / 15 phút"]\nF2 --> F3["3 · JWT<br/>chữ ký, hạn"]\nF3 --> F4["4 · Phân quyền<br/>route + role<br/>mặc định chặn"]\nF4 --> F5["5 · Phiên<br/>credential<br/>Version"]\nF5 --> S["Service đích<br/>@PreAuthorize"]\nF2 -.->|"429"| X["ApiResponse lỗi<br/>+ correlationId"]\nF3 -.->|"401"| X\nF4 -.->|"403"| X\nF5 -.->|"401 / 403"| X',
 bullets:[['Danh tính xuống service','Xóa X-User-Id, X-Staff-Id… client tự gửi; chỉ gắn lại từ JWT đã kiểm'],['Endpoint công khai','Chỉ login, refresh, quên/đặt lại mật khẩu, health: allowlist chính xác'],['Lỗi thống nhất','Mọi lỗi Gateway cùng envelope ApiResponse; 503/504 khi service không phản hồi']],
 handoff:'Demo: mở API không token → 401; CASHIER gọi /api/v1/patients → 403; xem X-Correlation-Id trong Network',
 notes:'backend/gateway/.../filter: CorrelationIdWebFilter (HIGHEST_PRECEDENCE), PublicAuthRateLimitWebFilter (theo địa chỉ socket, không tin X-Forwarded-For), JwtAuthenticationFilter (order -1), RouteAuthorizationFilter (order 0, AUTH_FORBIDDEN), AccountSessionValidationFilter (order 1: AUTH_SESSION_REVOKED, AUTH_PASSWORD_CHANGE_REQUIRED), GatewayExceptionHandlingFilter. PublicEndpointPolicy là allowlist. Defense in depth: service kiểm @PreAuthorize (docs/ai/07-security-rbac.md).'});
add({type:'canvas',section:'07 / GATEWAY · ĐĂNG NHẬP',title:'Đăng nhập: Gateway phát JWT sau khi Organization xác minh',owner:'Hoàng Anh',service:'Gateway · Organization (Core)',time:'2 phút',
 diagram:'sequenceDiagram\nparticipant U as Web / Mobile\nparticipant G as Gateway\nparticipant O as Organization (Core)\nparticipant S as Service nghiệp vụ\nU->>G: POST /api/v1/auth/login (email, mật khẩu)\nG->>O: Xác minh tài khoản (timeout 1,5s, circuit breaker)\nO-->>G: accountId, role, staffId / patientId, credentialVersion\nG-->>U: accessToken 30 phút + refreshToken 24 giờ\nU->>G: GET /api/... Authorization: Bearer\nG->>G: Kiểm JWT, role, phiên tài khoản\nG->>S: Chuyển tiếp + X-User-Id, X-User-Role, X-Correlation-Id\nS-->>U: ApiResponse',
 bullets:[['Lần đầu đăng nhập','Token mang cờ mustChangePassword: UI chuyển sang đổi mật khẩu, Gateway chặn API khác'],['Thu hồi phiên','Khóa tài khoản hoặc cấp lại mật khẩu tăng credentialVersion: token cũ bị từ chối ngay'],['Organization chậm','Gateway trả 504/503 rõ ràng, không treo client']],
 handoff:'Hoàng Anh tiếp tục Organization: tạo dữ liệu nền cho lượt khám',
 notes:'backend/gateway/.../auth/AuthController.java (login, refresh), OrganizationAuthClient (mediflow.organization-auth: timeout 1500 ms, failure-rate 50%, cửa sổ 10, mở 10 s), security/JwtTokenService (access 30 phút, refresh 1440 phút), filter/AccountSessionValidationFilter. Mật khẩu không bao giờ trả qua API.'});
add({section:'03 / ADMIN QUẢN LÝ',title:'Chuẩn bị khoa, nhân sự và tài khoản',owner:'Hoàng Anh',service:'Organization · Core :8089',time:'2 phút',role:'ADMIN',route:'/organization/departments · /organization/staff · /organization/accounts',rows:[['UI: lưu khoa mới','department.created'],['UI: tạo nhân viên','staff.created'],['UI: đổi khoa của nhân viên','staff.department.changed']],diagram:flow('U["Admin · Lưu khoa / nhân viên"] --> O["Organization · ghi dữ liệu + outbox"]\nO -->|"department.created / staff.created"| '+mq+'\nR --> Q["Queue có binding phù hợp"]'),proof:'Hiển thị khoa và nhân viên vừa tạo; đối chiếu routing key tại exchange. Không nói Report nhận event tổ chức nếu không có binding.',handoff:'Dữ liệu khoa/bác sĩ sẵn sàng → chuyển Patient tiếp nhận người bệnh',notes:source.org+' | Đăng nhập/cấp tài khoản không tự đồng nghĩa department.created/staff.created. Sửa thông tin liên hệ có staff.contact.updated; chỉ demo nếu cần. Organization giữ account identity. Lịch nhận khám và sức chứa thuộc Clinical, không thuộc Organization. Không cần tạo mới mọi danh mục nếu đã có dữ liệu seed hợp lệ.'});
add({section:'04 / BỆNH NHÂN ĐẾN KHÁM',title:'Tìm đúng hồ sơ trước khi tạo bệnh nhân mới',owner:'Hoàng Anh',service:'Patient · Core :8089',time:'2 phút',role:'NURSE / tiếp nhận',route:'/patients → /patients/new → chi tiết bệnh nhân',rows:[['UI: tìm hồ sơ theo định danh','GET / đọc dữ liệu · không phát event'],['UI: lưu bệnh nhân mới','patient.created'],['UI: lưu chỉnh sửa hồ sơ','patient.updated']],diagram:flow('U["Tiếp nhận · Lưu bệnh nhân"] --> P["Patient · patientId + outbox"]\nP -->|"patient.created"| '+mq+'\nR --> Q["notification.q"]\nQ --> N["Notification · thông báo chào mừng"]'),proof:'Giữ patientId vừa tạo; hồ sơ tồn tại dù cấp account gặp lỗi. Cấp tài khoản PATIENT từ hồ sơ, dùng email theo contract hiện hành.',handoff:'Bàn giao patientId và khoa → Vinh đăng ký lượt khám',notes:source.patient+' | Tái sử dụng hồ sơ khi bệnh nhân quay lại. Cấp account là command Organization riêng, không tạo patient lần hai. Contract email 04/11/2026 ở đầu docs/plans/03-contracts.md thay mô tả username CCCD/mật khẩu 1 cũ phía dưới. Không đọc mật khẩu qua API; mail bảo mật của Organization khác Notification in-app. patient.archived là nhánh quản trị phụ, không dùng trong lượt demo chính.'});
add({section:'05 / ĐĂNG KÝ NGOẠI TRÚ',title:'Đăng ký và giữ chỗ trước khi thu phí khám',owner:'Vinh',service:'Clinical · :8082',time:'2 phút',role:'NURSE; ADMIN/MANAGER quản lý lịch',route:'/appointments/department → /appointments/new',rows:[['UI: chọn lịch, khoa, bác sĩ','Clinical kiểm lịch và sức chứa'],['UI: xác nhận đăng ký tại quầy','outpatient.registration.changed'],['Trạng thái chờ thu','Có mã lượt / registration; chưa coi là đã khám']],diagram:flow('U["UI · Đăng ký tại quầy"] --> C["Clinical · registration + reservation"]\nC -->|"outpatient.registration.changed"| '+mq+'\nR --> B["Billing · chuẩn bị khoản thu EXAM"]'),proof:'Phiếu cùng patientId, bác sĩ/khoa, giờ dự kiến và số tiền cần thu. Tiếp nhận tại quầy ghi nhận đã có mặt trong cùng intent.',handoff:'Giữ nguyên mã lượt → Lộc thu phí khám ở slide 07',notes:source.clinical+' | Kịch bản chính chọn scheduled registration, cần scheduling UI/backend và issuer tương ứng được bật/kiểm thử. Legacy appointment.created và appointment.status.changed là contract khác, không trộn với scheduled flow. Registration chưa đủ tài chính không đồng nghĩa phiếu đã confirmed. Cần chuẩn bị lịch đang mở trước buổi demo.'});
function billing(purpose,section,title,route,handoff){
 const exam=purpose==='EXAM';
 add({section,title,owner:'Lộc',service:'Billing · :8086',time:'1–2 phút',role:'CASHIER',route,rows:[['UI: chọn đúng khoản '+purpose,'Đọc lại nguồn, số tiền và báo giá từ Billing'],['UI: xác nhận thu tiền','payment.completed'],['Sau đủ nghĩa vụ tài chính',exam?'outpatient.financial.eligibility.granted':'financial.clearance.granted']],diagram:flow('U["Thu ngân · Xác nhận thanh toán"] --> B["Billing · payment + outbox"]\nB -->|"payment.completed"| '+mq+'\nB -->|"'+(exam?'outpatient.financial.eligibility.granted':'financial.clearance.granted')+'"| R\nR --> C["'+(exam?'Clinical · xác nhận phiếu':'Nguồn '+purpose+' · đủ điều kiện thực hiện')+'"]\nR --> S["Report / Notification · queue riêng"]'),proof:exam?'Clinical đọc lại được phiếu đã xác nhận. Không lấy HTTP thanh toán thành công làm bằng chứng consumer đã xử lý.':purpose==='LAB_TEST'?'Lab chuyển đủ điều kiện / READY cho đúng phiếu. Chưa có clearance thì không bắt đầu xét nghiệm.':'Đơn thuốc đủ điều kiện cấp; payment thành công chưa có nghĩa thuốc đã xuất khỏi kho.',handoff,notes:source.billing+' | Dùng contract đúng nhánh: scheduled EXAM dùng outpatient.financial.eligibility.granted; Lab/Rx V1 dùng financial.clearance.granted. invoice.created gắn bước issuer tạo yêu cầu, không phải mỗi click vào danh sách. Nhánh nghĩa vụ 0 dùng command eligibility riêng, không tạo payment 0. Không gộp 3 loại phí thành 1 khoản tùy ý. Timeout: tra cứu outcome, retry cùng idempotency key. Report/Notification chỉ xử lý khi profile và bindings đúng. Các sơ đồ bỏ bớt consumer phụ cho dễ theo dõi.'});
}
billing('EXAM','06 / THU PHÍ KHÁM','Thu phí khám, sau đó mới xác nhận phiếu','/billing/scheduled-payments','Lộc → Vinh: phiếu đã confirmed và đã có mặt → bắt đầu khám');
add({section:'07 / BÁC SĨ KHÁM',title:'Mở hồ sơ khám và tạo chỉ định đúng lượt',owner:'Vinh',service:'Clinical · :8082',time:'2 phút',role:'DOCTOR được phân công',route:'/appointments/[id] → /records/[id] → lab-order',rows:[['UI: bắt đầu khám / lưu hồ sơ','appointment.status.changed / medicalrecord.created, theo command'],['UI: lưu chẩn đoán','diagnosis.added'],['UI: lưu chỉ định xét nghiệm','Lưu Clinical Lab Order; không gán event lab.request.created tại bước này']],diagram:flow('U["Bác sĩ · Lưu hồ sơ / chẩn đoán"] --> C["Clinical · hồ sơ đang mở"]\nC -->|"medicalrecord.created / diagnosis.added"| '+mq+'\nC --> O["Lưu chỉ định · sourceOrderId"]\nO -->|"UI chuyển bước + Lab kiểm nguồn bằng REST"| L["Lab · tạo yêu cầu ở slide 09"]'),proof:'Ghi triệu chứng, chẩn đoán, mã chỉ định và recordId. medicalrecord.created không tự tạo một xét nghiệm từ chẩn đoán.',handoff:'Vinh chuyển vai LAB_TECH → tạo yêu cầu từ chỉ định đã lưu',notes:source.clinical+' | ClinicalLabOrderApplicationService lưu order dưới hồ sơ OPEN và appointment IN_EXAM, kiểm assigned doctor. Không có event phát cho create order trong service đã đọc; không phát minh clinical.lab.ordered. Lab đọc source context qua authority API, không SQL sang Clinical. Nút UI diễn đạt theo thao tác, không cam kết mọi nhãn bằng nhau giữa các nhánh UI.'});
add({section:'08 / LAB NHẬN CHỈ ĐỊNH',title:'Tạo phiếu Lab từ chỉ định của bác sĩ',owner:'Vinh',service:'Lab · :8084',time:'1 phút',role:'LAB_TECH theo quyền nguồn',route:'/records/[recordId]/lab-order → /lab/[testId]',rows:[['UI: tạo yêu cầu từ chỉ định','Lab xác minh sourceOrderId với Clinical qua REST'],['Sau khi tạo yêu cầu thành công','lab.request.created'],['Kết quả phía Billing','Khoản thu LAB_TEST đúng source, patient và lượt']],diagram:flow('U["UI · Tạo yêu cầu xét nghiệm"] --> L["Lab · kiểm chỉ định qua REST"]\nL -->|"lab.request.created"| '+mq+'\nR --> B["Billing · LAB_TEST payment request"]'),proof:'Phiếu Lab có recordId/sourceOrderId và patientId đúng; trạng thái chưa được phép thực hiện khi còn thiếu clearance.',handoff:'Vinh → Lộc: thu phí xét nghiệm trước khi bấm Bắt đầu xét nghiệm',notes:source.lab+' | Source-based request V1 và contract source fields phải đúng, không tạo UUID giả. Không mô tả queue lab.q nhận lab.request.created để tự sinh phiếu thứ hai. lab.request.created là fact do Lab tạo sau khi phiếu được ghi.'});
billing('LAB_TEST','09 / THU PHÍ XÉT NGHIỆM','Thanh toán Lab để mở quyền thực hiện','/billing/payment-requests → chọn LAB_TEST','Lộc → Vinh: kiểm tra Lab đã READY và có clearanceId');
add({section:'10 / LAB TRẢ KẾT QUẢ',title:'Thực hiện xét nghiệm và lưu kết quả',owner:'Vinh',service:'Lab · :8084',time:'2 phút',role:'LAB_TECH',route:'/lab/[testId]',rows:[['UI: Bắt đầu xét nghiệm','Kiểm READY + clearanceId trong luồng V1'],['UI: Nhập kết quả → Lưu kết quả','lab.result.created'],['UI: xem kết quả trên hồ sơ khám','Đọc kết quả cùng lượt, không thu phí khám lần hai']],diagram:flow('U["Lab UI · Lưu kết quả"] --> L["Lab · COMPLETED"]\nL -->|"lab.result.created"| '+mq+'\nR --> N["notification.q · báo có kết quả"]\nR --> T["report.outpatient-v1.q · thống kê"]\nC["Bác sĩ · đọc kết quả"] -->|"HTTP qua Gateway"| L'),proof:'Chỉ số, đơn vị, khoảng tham chiếu và kết luận hiển thị. Bác sĩ đọc lại kết quả trong hồ sơ hiện tại.',handoff:'Vinh kết luận chuyên môn → Huy trình bày Pharmacy trên hồ sơ này',notes:source.lab+' | Không khẳng định Clinical nhận event để sao chép toàn bộ Lab result. Clinical có thể đọc qua contract/source context. Hủy là nhánh riêng lab.request.cancelled: Billing xử lý nghĩa vụ/void/refund theo trạng thái; không nói hủy tự hoàn tiền. Notification chỉ báo có kết quả, không chứa toàn bộ chỉ số.'});
add({section:'11 / KÊ ĐƠN',title:'Tạo đơn thuốc gắn với hồ sơ đang khám',owner:'Huy',service:'Pharmacy · :8085',time:'2 phút',role:'DOCTOR tạo đơn; PHARMACIST quản lý kho',route:'/pharmacy/prescriptions/new',rows:[['UI: chọn hồ sơ, thuốc, số lượng','Pharmacy kiểm Clinical context và tồn kho'],['UI: Tạo đơn thuốc','prescription.created'],['Billing nhận nguồn đơn','Chuẩn bị khoản thu PRESCRIPTION']],diagram:flow('U["Bác sĩ · Tạo đơn thuốc"] --> P["Pharmacy · đơn + giữ tồn theo contract"]\nP -->|"prescription.created"| '+mq+'\nR --> B["Billing · khoản thu PRESCRIPTION"]'),proof:'Có prescriptionId, đúng patient/record/lượt và chi tiết thuốc. Kê đơn là quyết định của bác sĩ; Huy là người trình bày service.',handoff:'Huy → Lộc: thu tiền đơn thuốc; chưa bấm xuất thuốc',notes:source.pharmacy+' | Phân biệt người thuyết trình với vai nghiệp vụ. Context lookup/identity/stock reservation phải sẵn sàng. Không nhập đơn không có authority nguồn để làm cho demo đi tiếp. stock.adjusted gắn điều chỉnh kho; stock.low chỉ phát khi điều kiện tồn thấp xảy ra, không luôn đi kèm mọi đơn.'});
billing('PRESCRIPTION','12 / THU TIỀN THUỐC','Thu tiền đúng đơn, rồi bàn giao quầy thuốc','/billing/payment-requests → chọn PRESCRIPTION','Lộc → Huy: kiểm clearance đúng đơn rồi xuất thuốc');
add({section:'13 / BỆNH NHÂN NHẬN THUỐC',title:'Xuất thuốc là một bước riêng sau thanh toán',owner:'Huy',service:'Pharmacy · :8085',time:'2 phút',role:'PHARMACIST',route:'/pharmacy/prescriptions/[prescriptionId]',rows:[['UI: kiểm đơn và trạng thái thu','Đọc lại clearance / trạng thái hợp lệ'],['UI: Xác nhận xuất thuốc','prescription.filled'],['Nhánh lỗi để giải thích','prescription.dispense.failed · không xuất kho giả']],diagram:flow('U["Dược sĩ · Xác nhận xuất thuốc"] --> P["Pharmacy · ghi dispense / cập nhật kho"]\nP -->|"prescription.filled"| '+mq+'\nR --> B["Billing · ghi nhận đơn đã thực hiện"]\nR --> S["Report / Notification"]'),proof:'Đơn đã cấp thuốc, có bằng chứng xuất thuốc và tồn kho thay đổi phù hợp. Nếu cấp lỗi sau thu: xử lý đối soát/hoàn tiền theo nghiệp vụ.',handoff:'Huy → Vinh: hoàn tất hồ sơ khám và hướng dẫn ra về',notes:source.pharmacy+' | Luồng V0 có thể xử lý payment.completed khác luồng V1 clearance + explicit dispense. Slide này dùng nhánh V1: không nói payment.completed tự cấp thuốc. Failure/refund là nhánh phụ; không cần cố tình phá dữ liệu chính. Replay cùng event không được xuất thuốc lần hai.'});
add({section:'14 / KẾT THÚC LƯỢT KHÁM',title:'Hoàn tất hồ sơ và hướng dẫn bệnh nhân ra về',owner:'Vinh',service:'Clinical · :8082',time:'1–2 phút',role:'DOCTOR',route:'/records/[recordId] → Hoàn tất lần khám',rows:[['UI: đọc Lab, lưu kết luận','Tiếp tục cùng hồ sơ; không tạo lượt mới'],['UI: Hoàn tất hồ sơ khám','medicalrecord.completed'],['UI: lưu lời hẹn tái khám nếu dùng','followup.recommendation.created']],diagram:flow('U["Bác sĩ · Hoàn tất hồ sơ khám"] --> C["Clinical · COMPLETED"]\nC -->|"medicalrecord.completed"| '+mq+'\nR --> N["Notification · kết quả khám đã có"]\nR --> T["Report · lượt khám hoàn tất"]'),proof:'Kết luận, hướng dẫn và thời điểm hoàn tất hiển thị. Bệnh nhân đã xử lý các nghĩa vụ tài chính và nhận thuốc nếu có.',handoff:'Vinh → Lộc: đăng nhập PATIENT xem thông báo và kết quả cá nhân',notes:source.clinical+' | Hoàn tất hồ sơ không đồng nghĩa tự settle mọi khoản phí. Kiểm pending Lab/nguồn nghiệp vụ theo guard hiện tại. Lời hẹn tái khám là recommendation, chưa giữ suất hoặc chứng minh đã thu tiền. Portal /records/mine chỉ trả hồ sơ completed; /lab/mine chỉ trả kết quả completed thuộc principal.'});
add({section:'15 / THÔNG BÁO CÁ NHÂN',title:'Nhận event, lưu thông báo cho đúng bệnh nhân',owner:'Lộc',service:'Notification · Support :8087',time:'2 phút',role:'PATIENT',route:'/notifications · /records/mine · /lab/mine',rows:[['Tự động khi event nguồn tới','Nhận patient.created / lab.result.created / medicalrecord.completed'],['Sau khi lưu thông báo thành công','notification.sent'],['UI: mở thông báo / xem kết quả','Đọc dữ liệu · không tự phát lab.result.created']],diagram:flow('P["Patient / Lab / Clinical"] -->|"event nghiệp vụ"| '+mq+'\nR --> Q["notification.q"]\nQ --> N["Notification · lưu IN_APP + outbox"]\nN -->|"notification.sent"| R\nU["PATIENT · xem thông báo"] -->|"HTTP qua Gateway"| N'),proof:'Đúng bệnh nhân thấy thông báo có kết quả; mở cổng cá nhân đọc chi tiết từ Clinical/Lab. Nhận lại event không nhân đôi thông báo.',handoff:'Lộc → Huy: báo cáo cuối lượt từ các facts đã ghi nhận',notes:source.notification+' | notification.sent thể hiện xử lý gửi/lưu theo contract, không chứng minh người bệnh đã đọc hoặc SMS/email đã đến. Luồng này chọn IN_APP. notification.sent không được vẽ quay lại notification.q nếu không có binding tương ứng. Source events có dạng flat và nested khác nhau; dùng decoder/version đúng. Patient không dùng patientId tùy ý để xem kết quả người khác.'});
add({section:'16 / BÁO CÁO CUỐI LUỒNG',title:'Đối chiếu một lượt khám từ các event nguồn',owner:'Huy',service:'Report · Support :8087',time:'2 phút',role:'MANAGER / ADMIN theo quyền báo cáo',route:'/reports/outpatient',rows:[['Event nghiệp vụ nhận vào','medicalrecord.completed · lab.result.created · prescription.filled'],['Event tài chính nhận vào','payment.completed · payment.refunded'],['UI: chọn kỳ / xem biểu đồ','Đọc read model · không phát report.generated']],diagram:flow('P["Clinical / Lab / Pharmacy / Billing"] -->|"facts đã xảy ra"| '+mq+'\nR --> Q["report.outpatient-v1.q"]\nQ --> T["Report · read model / kỳ đã được chấp nhận"]\nU["Manager · chọn kỳ báo cáo"] -->|"GET qua Gateway"| T'),proof:'Đối chiếu lượt khám, Lab, đơn đã cấp và tiền thu theo kỳ dữ liệu đã được chấp nhận. Phân biệt thu tiền, hỗ trợ mô phỏng và hoàn tiền.',handoff:'Huy chốt demo: cùng một bệnh nhân, các service phối hợp qua hợp đồng rõ ràng',notes:source.report+' | report.outpatient-v1.q là intake ngoại trú có gate; report.q là queue legacy với bindings khác. /reports/outpatient có capability/accepted-period gates: không hứa dữ liệu của lượt vừa tạo sẽ hiển thị ngay trên kỳ đã publish. Chuẩn bị kỳ accepted phù hợp; nói rõ độ trễ và thời điểm snapshot. Report đọc store của mình, không JOIN DB Billing. Không tạo event report.generated chỉ vì nhấn xem thống kê.'});
add({type:'checklist',section:'17 / ĐỐI CHIẾU & CHẠY THỬ',title:'Một dữ liệu demo, bốn người bàn giao rõ ràng',owner:'Cả nhóm',time:'1 phút',notes:'Đây là checklist chuẩn bị, chưa xác nhận hệ thống đang chạy hoặc acceptance đã đạt. Không tự bật toàn bộ cờ. Đọc docs/plans/06-acceptance-runbook.md, docs/plans/20-email-account-demo-runbook-2026-11-04.md và profile thực tế. Source baseline 8d6c287d; làm slide ngày 04/11/2026.',diagram:flow('U["Một thao tác ghi trên UI"] --> S["Service · ghi nghiệp vụ / outbox tùy nhánh"]\nS -->|"routing key + eventId"| '+mq+'\nR --> Q["Queue consumer đúng binding"]\nQ --> C["Consumer · dedupe + lưu effect"]\nQ -.->|"Lỗi quá số lần retry"| D["mediflow.events.dlx → DLQ"]'),rows:[['Trước buổi demo','Khởi động 6 business apps; seed khoa/bác sĩ/thuốc/lịch; kiểm tài khoản và quyền.'],['Chốt profile','Scheduled EXAM; Lab/Rx clearance; Notification IN_APP; Report consumer/read/accepted period.'],['Bộ mã dùng chung','patientId → registration/appointmentId → recordId → testId → prescriptionId → paymentId.'],['Bằng chứng trên RabbitMQ','Mở :15672, chỉ exchange, routing key, bindings, consumer và DLQ. Queue rỗng có thể đã xử lý xong.'],['Khi timeout','Tra cứu kết quả; retry đúng intent/key; không tạo đơn hay thu tiền mới để che outcome chưa rõ.']],handoff:'Phím ← → chuyển slide · G mục lục · N ghi chú · M mã Mermaid · F toàn màn hình · P in / PDF'});
slides.forEach((s,i)=>{if(/^\d\d \/ /.test(s.section))s.section=String(i).padStart(2,'0')+s.section.slice(2)});
{const team=slides.find(s=>s.type==='team');const pad=n=>String(n).padStart(2,'0');const ranges=n=>n.reduce((a,x)=>{const l=a[a.length-1];if(l&&l[1]===x-1)l[1]=x;else a.push([x,x]);return a},[]).map(([a,b])=>a===b?pad(a):pad(a)+'–'+pad(b)).join(', ');team.rows.forEach(r=>{r[3]=ranges(slides.map((s,i)=>s.owner===r[0]?i+1:0).filter(Boolean))})}
let diagrams=0;
function diagram(s,i,key='diagram',suffix=''){const src=s[key];if(!src)return '';fs.writeFileSync(path.join(out,'diagrams',String(i+1).padStart(2,'0')+suffix+'.mmd'),src);diagrams++;let svg=renderMermaidSVG(src,{bg:'#eef5f5',fg:'#0f2c30',accent:'#0f766e',line:'#4a6467',surface:'#ffffff',border:'#b8d3d3',font:'Arial',padding:20,nodeSpacing:20,layerSpacing:32});return `<div class="diagram" tabindex="0" role="button" aria-label="Phóng to sơ đồ" data-zoom="${i}">${prepareSvgForPng(cleanSvg(svg)).svg}</div>`}
function service(s,i){const d=diagram(s,i);return `<div class="${s.wide?'architecture':'columns'}"><div class="content"><div class="role">${esc(s.role||'Định tuyến · xác thực · discovery')}</div>${s.route?`<div class="route">${esc(s.route)}</div>`:''}<div class="rows">${s.rows.map(([a,b])=>`<div class="row"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('')}</div>${s.proof?`<div class="proof"><b>KIỂM CHỨNG TRÊN DEMO</b><p>${esc(s.proof)}</p></div>`:''}</div><div class="visual">${s.lead?`<p class="lead">${esc(s.lead)}</p>`:''}${d}<span class="caption">Sơ đồ Mermaid · bấm để phóng to</span></div></div><div class="handoff"><span>BÀN GIAO</span>${esc(s.handoff)}</div>`}
function body(s,i){if(s.type==='cover')return `<div class="cover-art">${MARK}</div><div class="cover-body"><svg class="pulse" viewBox="0 0 400 40" aria-hidden="true"><path d="M0 20H150L166 4L186 36L202 20H400"/></svg><p class="eyebrow">HỆ THỐNG QUẢN LÝ KHÁM NGOẠI TRÚ</p><h1>${s.title}</h1><p class="intro">${s.intro}</p><div class="cover-team"><span>Hoàng Anh<br><b>Gateway · Organization · Patient</b></span><span>Vinh<br><b>Clinical · Lab</b></span><span>Huy<br><b>Pharmacy · Report</b></span><span>Lộc<br><b>Billing · Notification</b></span></div><p class="cover-hint">${s.time} &nbsp; / &nbsp; UI → Service → RabbitMQ → Consumer</p></div>`;
if(s.type==='team')return `<table><thead><tr><th>Thành viên</th><th>Service phụ trách demo</th><th>Tasksheet ngắn gọn</th><th>Slide</th></tr></thead><tbody>${s.rows.map(r=>'<tr>'+r.map(c=>`<td>${esc(c)}</td>`).join('')+'</tr>').join('')}</tbody></table><div class="journey">${diagram(s,i)}</div><div class="handoff"><span>NHỊP TRÌNH BÀY</span>Hoàng Anh mở đầu → Vinh khám/Lab ↔ Lộc thu phí → Huy thuốc ↔ Lộc thu phí → Vinh kết luận → Lộc thông báo → Huy báo cáo</div>`;
if(s.type==='fr')return `<div class="fr-grid">${s.cards.map(([t,d],k)=>`<article class="fr-card"><b>FR-${String(k+1).padStart(2,'0')}</b><h3>${esc(t)}</h3><p>${esc(d)}</p></article>`).join('')}</div><div class="handoff"><span>PHI CHỨC NĂNG</span>${esc(s.handoff)}</div>`;
if(s.type==='canvas')return `<div class="cvs${s.arch?' arch':''}${s.full?' full':''}">${s.diagram2?`<div class="visual duo"><figure><figcaption>${esc(s.label1)}</figcaption>${diagram(s,i)}</figure><figure><figcaption>${esc(s.label2)}</figcaption>${diagram(s,i,'diagram2','b')}</figure>`:`<div class="visual">${diagram(s,i)}`}<span class="caption">Sơ đồ Mermaid · bấm để phóng to</span></div><div class="side">${s.bullets.map(([a,b])=>`<div class="row"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('')}</div></div><div class="handoff"><span>${s.owner==='Hoàng Anh'&&/Demo:/.test(s.handoff)?'DEMO':'GHI NHỚ'}</span>${esc(s.handoff.replace(/^Demo: /,''))}</div>`;
if(s.type==='checklist')return`<div class="columns checklist"><div class="rows">${s.rows.map(([a,b])=>`<div class="row"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('')}</div><div class="visual">${diagram(s,i)}</div></div><div class="handoff">${esc(s.handoff)}</div>`;
return service(s,i)}
