const js=`const slides=${payload}; let booted=false; let current=Math.max(0,Math.min(slides.length-1,(parseInt(location.hash.slice(1))||1)-1));const els=[...document.querySelectorAll('.slide')];const notes=document.querySelector('.notes');const drawer=document.querySelector('.drawer');const dlg=document.querySelector('dialog');function resize(){const fs=!!document.fullscreenElement;document.body.classList.toggle('fs',fs);const scale=fs?Math.min(innerWidth/1440,innerHeight/900):Math.min((innerWidth-40)/1440,(innerHeight-100)/900);els.forEach(e=>e.style.transform='scale('+scale+')')}function show(n){const prev=current;current=Math.max(0,Math.min(slides.length-1,n));if(booted&&prev===current)return;document.querySelector('#stage').classList.toggle('back',current<prev);els.forEach((e,i)=>{e.classList.remove('leaving');if(booted&&i===prev){e.classList.add('leaving');setTimeout(()=>e.classList.remove('leaving'),460)}e.classList.toggle('active',i===current);e.setAttribute('aria-hidden',String(i!==current))});history.replaceState(null,'','#'+(current+1));document.querySelector('#counter').textContent=(current+1)+' / '+slides.length;document.querySelector('.progress').style.width=((current+1)/slides.length*100)+'%';notes.innerHTML='<strong>GHI CHÚ NGƯỜI TRÌNH BÀY</strong>'+slides[current].notes;document.title='MediFlow · '+(current+1)+' / '+slides.length;booted=true}function toggleN(){notes.classList.toggle('open')}function toggleG(){drawer.classList.toggle('open')}function full(){if(!document.fullscreenElement)document.documentElement.requestFullscreen?.().catch(()=>{});else document.exitFullscreen?.()}function modal(mode,i=current,el){const s=slides[i];dlg.replaceChildren();const close=document.createElement('button');close.className='close';close.textContent='Đóng ×';close.onclick=()=>dlg.close();dlg.append(close);const h=document.createElement('h2');h.textContent=s.title.replaceAll('<br>',' ');dlg.append(h);if(mode==='source'){const p=document.createElement('p');p.className='dialog-help';p.textContent='Mã nguồn Mermaid của sơ đồ trên slide. Các bản .mmd nằm trong thư mục diagrams/.';dlg.append(p);const pre=document.createElement('pre');pre.textContent=[s.diagram,s.diagram2].filter(Boolean).join('\\n\\n%% ----\\n\\n')||'Slide này không có sơ đồ Mermaid.';dlg.append(pre)}else {const original=el||els[i].querySelector('.diagram');if(!original)return;const clone=original.cloneNode(true);clone.removeAttribute('data-zoom');clone.removeAttribute('role');dlg.append(clone)}dlg.showModal()}document.querySelector('#prev').onclick=()=>show(current-1);document.querySelector('#next').onclick=()=>show(current+1);document.querySelector('#toc').onclick=toggleG;document.querySelector('#note').onclick=toggleN;document.querySelector('#mermaid').onclick=()=>modal('source');document.querySelector('#full').onclick=full;document.querySelector('#print').onclick=()=>window.print();slides.forEach((s,i)=>{const b=document.createElement('button');b.textContent=String(i+1).padStart(2,'0')+' · '+s.owner+' · '+s.title.replaceAll('<br>',' ');b.onclick=()=>{show(i);drawer.classList.remove('open')};drawer.append(b)});document.querySelectorAll('[data-zoom]').forEach(e=>{e.onclick=()=>modal('zoom',+e.dataset.zoom,e);e.onkeydown=ev=>{if(ev.key==='Enter')modal('zoom',+e.dataset.zoom,e)}});addEventListener('keydown',e=>{if(dlg.open)return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(current+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(current-1)}if(e.key==='Home')show(0);if(e.key==='End')show(slides.length-1);if(e.key.toLowerCase()==='n')toggleN();if(e.key.toLowerCase()==='g')toggleG();if(e.key.toLowerCase()==='m')modal('source');if(e.key.toLowerCase()==='f')full();if(e.key.toLowerCase()==='p')window.print();if(e.key==='Escape'){notes.classList.remove('open');drawer.classList.remove('open')}});addEventListener('resize',resize);addEventListener('hashchange',()=>show((parseInt(location.hash.slice(1))||1)-1));let tx=0;addEventListener('touchstart',e=>tx=e.changedTouches[0].screenX,{passive:true});addEventListener('touchend',e=>{if(dlg.open)return;const dx=e.changedTouches[0].screenX-tx;if(Math.abs(dx)>70)show(current+(dx<0?1:-1))},{passive:true});document.addEventListener('fullscreenchange',resize);let uiTimer;addEventListener('mousemove',()=>{document.body.classList.add('ui');clearTimeout(uiTimer);uiTimer=setTimeout(()=>document.body.classList.remove('ui'),2200)});resize();show(current);`;
